"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[41218],{29055:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>d,contentTitle:()=>r,default:()=>c,frontMatter:()=>s,metadata:()=>o,toc:()=>i});var a=n(31085),h=n(71184);const s={sidebar_position:3,slug:"/bible/1_Machabees/1_Machabees_3",title:"1 Machabees 3",hide_table_of_contents:!0},r="1 Machabees",o={id:"bible/1 Machabees/1 Machabees 3",title:"1 Machabees 3",description:"Chapter 3",source:"@site/docs/bible/1 Machabees/1 Machabees 3.md",sourceDirName:"bible/1 Machabees",slug:"/bible/1_Machabees/1_Machabees_3",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_3",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/1 Machabees/1 Machabees 3.md",tags:[],version:"current",sidebarPosition:3,frontMatter:{sidebar_position:3,slug:"/bible/1_Machabees/1_Machabees_3",title:"1 Machabees 3",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"1 Machabees 2",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_2"},next:{title:"1 Machabees 4",permalink:"/bibleNotes/docs/bible/1_Machabees/1_Machabees_4"}},d={},i=[{value:"Chapter 3",id:"chapter-3",level:2}];function l(e){const t={h1:"h1",h2:"h2",p:"p",...(0,h.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.h1,{id:"1-machabees",children:"1 Machabees"}),"\n",(0,a.jsx)(t.h2,{id:"chapter-3",children:"Chapter 3"}),"\n",(0,a.jsx)(t.p,{children:"Judas Machabeus succeeds his father, and overthrows Apollonius and Seron.  A great army is sent against him out of Syria.  He prepares his people for battle by fasting and prayer."}),"\n",(0,a.jsx)(n,{verse:1,children:"Then his son Judas, called Machabeus, rose up in his stead."}),"\n",(0,a.jsx)(n,{verse:2,children:"And all his brethren helped him, and all they that had joined themselves to his father, and they fought with cheerfulness the battle of Israel."}),"\n",(0,a.jsx)(n,{verse:3,children:"And he got his people great honour, and put on a breastplate as a giant, and girt his warlike armour about him in battles, and protected the camp with his sword."}),"\n",(0,a.jsx)(n,{verse:4,children:"In his acts he was like a lion, and like a lion's whelp roaring for his prey."}),"\n",(0,a.jsx)(n,{verse:5,children:"And he pursued the wicked and sought them out, and them that troubled his people he burnt with fire:"}),"\n",(0,a.jsx)(n,{verse:6,children:"And his enemies were driven away for fear of him, and all the workers of iniquity were troubled: and salvation prospered in his hand."}),"\n",(0,a.jsx)(n,{verse:7,children:"And he grieved many kings, and made Jacob glad with his works, and his memory is blessed for ever."}),"\n",(0,a.jsx)(n,{verse:8,children:"And he went through the cities of Juda, and destroyed the wicked out of them, and turned away wrath from Israel."}),"\n",(0,a.jsx)(n,{verse:9,children:"And he was renowned even to the utmost part of the earth, and he gathered them that were perishing."}),"\n",(0,a.jsx)(n,{verse:10,children:"And Apollonius gathered together the Gentiles, and a numerous and great army from Samaria, to make war against Israel."}),"\n",(0,a.jsx)(n,{verse:11,children:"And Judas understood it, and went forth to meet him: and he overthrew him, and killed him: and many fell down slain, and the rest fled away."}),"\n",(0,a.jsx)(n,{verse:12,children:"And he took their spoils, and Judas took the sword of Apollonius, and fought with it all his lifetime."}),"\n",(0,a.jsx)(n,{verse:13,children:"And Seron, captain of the army of Syria, heard that Judas had assembled a company of the faithful, and a congregation with him,"}),"\n",(0,a.jsx)(n,{verse:14,children:"And he said I will get me a name, and will be glorified in the kingdom, and will overthrow Judas, and those that are with him, that have despised the edict of the king."}),"\n",(0,a.jsx)(n,{verse:15,children:"And he made himself ready; and the host of the wicked went up with him, strong succours, to be revenged of the children of Israel."}),"\n",(0,a.jsx)(n,{verse:16,children:"And they approached even as far as Bethoron: and Judas went forth to meet him, with a small company."}),"\n",(0,a.jsx)(n,{verse:17,children:"But when they saw the army coming to meet them, they said to Judas: How shall we, being few, be able to fight against so great a multitude, and so strong, and we are ready to faint with fasting today?"}),"\n",(0,a.jsx)(n,{verse:18,children:"And Judas said: It is an easy matter for many to be shut up in the hands of a few: and there is no difference in the sight of the God of heaven to deliver with a great multitude, or with a small company:"}),"\n",(0,a.jsx)(n,{verse:19,children:"For the success of war is not in the multitude of the army, but strength cometh from heaven."}),"\n",(0,a.jsx)(n,{verse:20,children:"They come against us with an insolent multitude, and with pride, to destroy us, and our wives, and our children, and to take our spoils."}),"\n",(0,a.jsx)(n,{verse:21,children:"But we will fight for our lives, and our laws:"}),"\n",(0,a.jsx)(n,{verse:22,children:"And the Lord himself will overthrow them before our face, but as for you, fear them not"}),"\n",(0,a.jsx)(n,{verse:23,children:"And as soon as he had made an end of speaking, he rushed suddenly upon them: and Seron, and his host were overthrown before him:"}),"\n",(0,a.jsx)(n,{verse:24,children:"And he pursued him by the descent of Bethoron, even to the plain, and there fell of them eight hundred men, and the rest fled into the land of the Philistines."}),"\n",(0,a.jsx)(n,{verse:25,children:"And the fear of Judas, and of his brethren, and the dread of them, fell upon all the nations round about them."}),"\n",(0,a.jsx)(n,{verse:26,children:"And his fame came to the king, and all nations told of the battles of Judas."}),"\n",(0,a.jsx)(n,{verse:27,children:"Now when king Antiochus heard these words, he was angry in his mind: and he sent, and gathered the forces of all his kingdom, an exceeding strong army."}),"\n",(0,a.jsx)(n,{verse:28,children:"And he opened his treasury, and gave out pay to the army for a year: and he commanded them, that they should be ready for all things."}),"\n",(0,a.jsx)(n,{verse:29,children:"And he perceived that the money of his treasures failed, and that the tributes of the country were small, because of the dissension, and the evil that he had brought upon the land, that he might take away the laws of old times:"}),"\n",(0,a.jsx)(n,{verse:30,children:"And he feared that he should not have as formerly enough for charges and gifts, which he had given before with a liberal hand: for he had abounded more than the kings that had been before him."}),"\n",(0,a.jsx)(n,{verse:31,children:"And he was greatly perplexed in mind, and purposed to go into Persia, and to take tributes of the countries, and to gather much money."}),"\n",(0,a.jsx)(n,{verse:32,children:"And he left Lysias, a nobleman of the blood royal to oversee the affairs of the kingdom from the river Euphrates even to the river of Egypt:"}),"\n",(0,a.jsx)(n,{verse:33,children:"And to bring up his son, Antiochus, till he came again."}),"\n",(0,a.jsx)(n,{verse:34,children:"And he delivered to him half the army, and the elephants: and he gave him charge concerning all that he would have done, and concerning the inhabitants of Judea, and Jerusalem."}),"\n",(0,a.jsx)(n,{verse:35,children:"And that he should send an army against them to destroy and root out the strength of Israel, and the remnant of Jerusalem, and to take away the memory of them from that place."}),"\n",(0,a.jsx)(n,{verse:36,children:"And that he should settle strangers, to dwell in all their coasts, and divide their land by lot."}),"\n",(0,a.jsx)(n,{verse:37,children:"So the king took the half of the army that remained, and went forth from Antioch, the chief city of his kingdom, in the hundred and forty-seventh year: and he passed over the river Euphrates, and went through the higher countries."}),"\n",(0,a.jsx)(n,{verse:38,children:"Then Lysias chose Ptolemee, the son of Dorymenus, and Nicanor, and Gorgias, mighty men of the king's friends."}),"\n",(0,a.jsx)(n,{verse:39,children:"And he sent with them forty thousand men, and seven thousand horsemen: to go into the land of Juda, and to destroy it, according to the king's orders."}),"\n",(0,a.jsx)(n,{verse:40,children:"So they went forth with all their power, and came, and pitched near Emmaus, in the plain country."}),"\n",(0,a.jsx)(n,{verse:41,children:"And the merchants of the countries heard the fame of them: and they took silver and gold in abundance, and servants: and they came into the camp, to buy the children of Israel for slaves: and there were joined to them the forces of Syria, and of the land of the strangers."}),"\n",(0,a.jsx)(n,{verse:42,children:"And Judas, and his brethren, saw that evils were multiplied, and that the armies approached to their borders: and they knew the orders the king had given to destroy the people, and utterly abolish them."}),"\n",(0,a.jsx)(n,{verse:43,children:"And they said, every man to his neighbour: Let us raise up the low condition of our people, and let us fight for our people, and our sanctuary."}),"\n",(0,a.jsx)(n,{verse:44,children:"And the assembly was gathered, that they might be ready for battle, and that they might pray, and ask mercy and compassion."}),"\n",(0,a.jsx)(n,{verse:45,children:"Now Jerusalem was not inhabited, but was like a desert: there was none of her children that went in or out: and the sanctuary was trodden down: and the children of strangers were in the castle, there was the habitation of the Gentiles: and joy was taken away from Jacob, and the pipe and harp ceased there."}),"\n",(0,a.jsx)(n,{verse:46,children:"And they assembled together, and came to Maspha, over against Jerusalem: for in Maspha was a place of prayer heretofore in Israel."}),"\n",(0,a.jsx)(n,{verse:47,children:"And they fasted that day, and put on haircloth, and put ashes upon their heads: and they rent their garments:"}),"\n",(0,a.jsx)(n,{verse:48,children:"And they laid open the books of the law, in which the Gentiles searched for the likeness of their idols:"}),"\n",(0,a.jsx)(n,{verse:49,children:"And they brought the priestly ornaments, and the first fruits and tithes, and stirred up the Nazarites that had fulfilled their days:"}),"\n",(0,a.jsx)(n,{verse:50,children:"And they cried with a loud voice toward heaven, saying: What shall we do with these, and whither shall we carry them?"}),"\n",(0,a.jsx)(n,{verse:51,children:"For thy holies are trodden down, and are profaned, and thy priests are in mourning, and are brought low."}),"\n",(0,a.jsx)(n,{verse:52,children:"And behold the nations are come together against us, to destroy us: thou knowest what they intend against us."}),"\n",(0,a.jsx)(n,{verse:53,children:"How shall we be able to stand before their face, unless thou, O God, help us?"}),"\n",(0,a.jsx)(n,{verse:54,children:"Then they sounded with trumpets, and cried out with a loud voice."}),"\n",(0,a.jsx)(n,{verse:55,children:"And after this, Judas appointed captains over the people, over thousands, and over hundreds, and over fifties, and over tens."}),"\n",(0,a.jsx)(n,{verse:56,children:"And he said to them that were building houses, or had betrothed wives, or were planting vineyards, or were fearful, that they should return every man to his house, according to the law."}),"\n",(0,a.jsx)(n,{verse:57,children:"So they removed the camp, and pitched on the south side of Emmaus."}),"\n",(0,a.jsx)(n,{verse:58,children:"And Judas said: Gird yourselves, and be valiant men, and be ready against the morning, that you may fight with these nations that are assembled against us to destroy us and our sanctuary."}),"\n",(0,a.jsx)(n,{verse:59,children:"For it is better for us to die in battle, than to see the evils of our nation, and of the holies:"}),"\n",(0,a.jsx)(n,{verse:60,children:"Nevertheless, as it shall be the will of God in heaven, so be it done."})]})}function c(e={}){const{wrapper:t}={...(0,h.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>o});var a=n(14041);const h={},s=a.createContext(h);function r(e){const t=a.useContext(s);return a.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(h):e.components||h:r(e.components),a.createElement(s.Provider,{value:t},e.children)}}}]);